-- V011 (PG): Bootstrap 初始化并发控制表（WP-BS-01 / WP-BOOTSTRAP-01）。
--
-- 设计基线：docs/superpowers/specs/2026-11-28-bootstrap-concurrency-control-design.md
-- 与 mysql/V011 语义对齐：DATETIME(6) → TIMESTAMPTZ、JSON → JSONB、
-- AUTO_INCREMENT → BIGINT GENERATED BY DEFAULT AS IDENTITY、
-- INSERT IGNORE → ON CONFLICT DO NOTHING。
--
-- ⚠️ 迁移执行器先按 ASCII 分号切分、再剥离 -- 注释行，注释里不能出现分号；
--   禁止 dollar-quote / DO 块 / CREATE FUNCTION / CREATE TRIGGER。

CREATE TABLE IF NOT EXISTS iam_bootstrap_init_gate (
    id INT NOT NULL PRIMARY KEY,
    status VARCHAR(16) NOT NULL DEFAULT 'idle',
    window_started_at TIMESTAMPTZ NULL,
    window_ends_at TIMESTAMPTZ NULL,
    winner_request_id BIGINT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())
;

CREATE TABLE IF NOT EXISTS iam_bootstrap_init_requests (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    status VARCHAR(16) NOT NULL DEFAULT 'collecting',
    steps JSONB NULL,
    execution_owner VARCHAR(64) NULL,
    execution_epoch BIGINT NOT NULL DEFAULT 0,
    lease_expires_at TIMESTAMPTZ NULL,
    started_at TIMESTAMPTZ NULL,
    finished_at TIMESTAMPTZ NULL,
    last_error VARCHAR(255) NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())
;

CREATE INDEX IF NOT EXISTS idx_iam_bootstrap_init_requests_status ON iam_bootstrap_init_requests (status)
;

-- 预建唯一 gate 控制行（幂等）：业务请求到来前必须已存在。
INSERT INTO iam_bootstrap_init_gate (id, status) VALUES (1, 'idle') ON CONFLICT (id) DO NOTHING
;
